// ADDERLEY MOSS — HTTP server: website, intake & consultations, e-signature and
// invoice links, client portal, practice-management console.
const express = require('express');
const compression = require('compression');
const path = require('path');
const crypto = require('crypto');
const D = require('./db');
const { one, all, run, tx, now, today, addDays, addMonths, J, setting, setSetting, token, log, hashPassword, verifyPassword } = D;
const L = require('./logic');
const { seed } = require('./seed');
if (seed()) console.log('Seeded demo firm');

const app = express(); app.disable('x-powered-by'); app.set('trust proxy', 1); app.use(compression()); app.use(express.json({ limit: '2mb' }));
app.use((req, res, next) => { res.setHeader('X-Content-Type-Options', 'nosniff'); res.setHeader('Referrer-Policy', 'same-origin'); res.setHeader('X-Frame-Options', 'SAMEORIGIN'); next(); });
const ROOT = path.join(__dirname, '..'), lib = (p) => path.join(ROOT, 'node_modules', p), so = { maxAge: process.env.NODE_ENV === 'production' ? '1h' : 0 };
app.use('/lib/gsap', express.static(lib('gsap/dist'), so)); app.use('/lib/three', express.static(lib('three/build'), so)); app.use('/lib/three-addons', express.static(lib('three/examples/jsm'), so));
for (const [k, p] of [['display', '@fontsource/libre-caslon-display'], ['serif', '@fontsource-variable/eb-garamond'], ['sans', '@fontsource-variable/schibsted-grotesk'], ['mono', '@fontsource/courier-prime'], ['sign', '@fontsource/mrs-saint-delafield']]) app.use('/fonts/' + k, express.static(lib(p + '/files'), { maxAge: '30d' }));
const SHOW_DEMO = process.env.SHOW_DEMO_LOGINS !== 'false';

const cookies = (req) => Object.fromEntries((req.headers.cookie || '').split(';').map((c) => c.trim().split('=')).filter((x) => x[0]).map(([k, ...v]) => [k, decodeURIComponent(v.join('='))]));
function startSession(res, userId) { const t = token(), exp = new Date(Date.now() + 14 * 864e5); run('INSERT INTO sessions (token, user_id, expires_at) VALUES (?,?,?)', t, userId, D.stamp(exp)); res.setHeader('Set-Cookie', `am_session=${t}; HttpOnly; Path=/; SameSite=Lax; Expires=${exp.toUTCString()}${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`); }
function currentUser(req) { const t = cookies(req).am_session; const s = t && one('SELECT s.expires_at, u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND u.active=1', t); if (!s || s.expires_at < now()) return null; delete s.password_hash; return s; }
const wrap = (fn) => async (req, res) => { try { const r = await fn(req, res); if (!res.headersSent) res.json(r ?? { ok: true }); } catch (e) { if (!res.headersSent) res.status(e.status || 400).json({ error: e.message }); } };
const auth = (...roles) => (req, res, next) => { const u = currentUser(req); if (!u) return res.status(401).json({ error: 'Please sign in' }); if (roles.length && !roles.includes(u.role)) return res.status(403).json({ error: 'Not allowed for your role' }); req.user = u; next(); };
const str = (v, max = 500) => { if (v == null) return null; const s = String(v).trim(); return s ? s.slice(0, max) : null; };
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(s || ''), isTime = (s) => /^\d{2}:\d{2}$/.test(s || ''), cents = (v) => Math.round(Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) * 100);
const hits = new Map(); function rateLimit(key, max, ms = 60000) { const t = Date.now(), a = (hits.get(key) || []).filter((x) => t - x < ms); if (a.length >= max) throw Object.assign(new Error('Too many attempts — try again in a minute'), { status: 429 }); a.push(t); hits.set(key, a); }
const testCard = (card) => { const n = String(card || '').replace(/\D/g, ''); if (n.length < 12) throw new Error('Enter a card number (test mode: 4242 4242 4242 4242)'); if (n.startsWith('4000')) throw new Error('Card declined — try another card'); return n.slice(-4); };
const firm = () => Object.fromEntries(['firm_name', 'firm_long', 'address', 'address2', 'phone', 'email', 'est', 'vat_rate'].map((k) => [k, setting(k, '')]));
const nf = (m = 'Not found') => Object.assign(new Error(m), { status: 404 });
const LAWYERS = "('managing_partner','partner','associate','paralegal')";
const person = (u) => ({ id: u.id, slug: u.slug, name: u.name, title: u.title, role: u.role, color: u.color, bar_year: u.bar_year, education: J(u.education, []), languages: u.languages, areas: J(u.areas, []), bio: u.bio, admissions: u.admissions });

app.get('/healthz', (req, res) => res.json({ ok: true }));
app.get('/api/config', (req, res) => res.json({ demo: SHOW_DEMO }));
app.post('/api/auth/login', wrap((req, res) => { rateLimit('login:' + req.ip, 15); const u = one('SELECT * FROM users WHERE email=? AND active=1', String(req.body.email || '').trim().toLowerCase()); if (!u || !verifyPassword(String(req.body.password || ''), u.password_hash)) throw new Error("That email and password don't match"); startSession(res, u.id); return { role: u.role, name: u.name }; }));
app.post('/api/auth/logout', (req, res) => { const t = cookies(req).am_session; if (t) run('DELETE FROM sessions WHERE token=?', t); res.setHeader('Set-Cookie', 'am_session=; Path=/; Max-Age=0'); res.json({ ok: true }); });
app.get('/api/me', auth(), (req, res) => res.json(req.user));

// ---------------------------------------------------------------- public
app.get('/api/public/info', wrap(() => ({
  firm: firm(), areas: Object.entries(L.AREAS).map(([k, a]) => ({ key: k, name: a.name, fee_cents: a.fee, stages: a.stages })), packages: L.PACKAGES,
  people: all(`SELECT * FROM users WHERE role IN ${LAWYERS} AND role<>'paralegal' AND active=1 ORDER BY CASE role WHEN 'managing_partner' THEN 0 WHEN 'partner' THEN 1 ELSE 2 END, bar_year`).map(person),
  articles: all('SELECT a.slug, a.title, a.area, a.dek, a.minutes, a.published_on, u.name AS author FROM articles a LEFT JOIN users u ON u.id=a.author_id ORDER BY published_on DESC'),
  stats: { years: new Date().getFullYear() - Number(setting('est', '1974')), matters: one('SELECT COUNT(*) n FROM matters').n, attorneys: one(`SELECT COUNT(*) n FROM users WHERE role IN ('managing_partner','partner','associate') AND active=1`).n, languages: 3 },
})));
app.get('/api/public/article/:slug', wrap((req) => { const a = one('SELECT a.*, u.name AS author, u.slug AS author_slug, u.title AS author_title FROM articles a LEFT JOIN users u ON u.id=a.author_id WHERE a.slug=?', req.params.slug); if (!a) throw nf(); return a; }));
app.post('/api/public/intake', wrap((req) => {
  rateLimit('intake:' + req.ip, 5); const b = req.body; if (!str(b.name) || (!str(b.email) && !str(b.phone))) throw new Error('Your name and an email or phone number are required'); if (!L.AREAS[b.area]) throw new Error('Choose the area of law');
  if (!b.consent) throw new Error('Please confirm you understand that no attorney-client relationship exists until we confirm in writing');
  const it = L.createIntake({ name: str(b.name, 100), email: str(b.email, 200)?.toLowerCase(), phone: str(b.phone, 30), company: str(b.company, 120), area: b.area, summary: str(b.summary, 3000), adverse: (Array.isArray(b.adverse) ? b.adverse : String(b.adverse || '').split(/[\n,;]+/)).map((x) => str(x, 120)).filter(Boolean), related: [], urgency: ['normal', 'high'].includes(b.urgency) ? b.urgency : 'normal', budget: str(b.budget, 40) });
  L.notify({ to: setting('email'), kind: 'intake', subject: `New enquiry ${it.number} — ${L.AREAS[it.area].name}`, body: `${it.name} · conflict status: ${it.status}` });
  return { token: it.token, status: it.status };
}));
const intakeByToken = (t) => { const i = one('SELECT * FROM intakes WHERE token=?', t); if (!i) throw nf('This link has expired'); return i; };
app.get('/api/public/intake/:token', wrap((req) => { const i = intakeByToken(req.params.token);
  const attys = all(`SELECT * FROM users WHERE role IN ('managing_partner','partner','associate') AND active=1`).filter((u) => J(u.areas, []).includes(i.area)).map(person);
  return { number: i.number, name: i.name, area: i.area, area_name: L.AREAS[i.area].name, status: i.status, consult_fee_cents: i.consult_fee_cents, consult_at: i.consult_at, consult_mode: i.consult_mode, consult_with: i.consult_user_id ? person(one('SELECT * FROM users WHERE id=?', i.consult_user_id)) : null, attorneys: attys, firm: firm() }; }));
app.get('/api/public/consult-slots', wrap((req) => { if (!isDate(req.query.date)) throw new Error('Pick a date'); return L.consultSlots(Number(req.query.user_id), req.query.date); }));
app.post('/api/public/intake/:token/book', wrap((req) => { rateLimit('book:' + req.ip, 6); const i = intakeByToken(req.params.token), b = req.body; if (!isDate(b.date) || !isTime(b.time)) throw new Error('Choose a date and time');
  const paid = i.consult_fee_cents > 0 ? !!testCard(b.card) : true; return L.bookConsult(i, { user_id: Number(b.user_id), date: b.date, time: b.time, mode: b.mode === 'video' ? 'video' : 'in_person', paid }, i.name).status; }));
app.post('/api/public/estimate/conveyancing', wrap((req) => { const p = cents(req.body.price); if (!(p >= 1000000)) throw new Error('Enter a price of at least B$10,000'); return L.conveyancingEstimate({ price_cents: p, side: req.body.side === 'seller' ? 'seller' : 'buyer', mortgage: !!req.body.mortgage, first_home: !!req.body.first_home }); }));
const docByToken = (t) => { const d = one('SELECT d.*, m.number AS matter_no, m.title AS matter_title FROM documents d LEFT JOIN matters m ON m.id=d.matter_id WHERE d.token=?', t); if (!d || !['sent', 'signed', 'declined'].includes(d.status)) throw nf('This signing link is not available'); return d; };
app.get('/api/public/sign/:token', wrap((req) => { const d = docByToken(req.params.token); return { name: d.name, body: d.body, status: d.status, signer_name: d.signer_name, signed_at: d.signed_at, matter_no: d.matter_no, matter_title: d.matter_title, firm: firm(), hash: crypto.createHash('sha256').update(d.body || '').digest('hex').slice(0, 16) }; }));
app.post('/api/public/sign/:token', wrap((req) => { rateLimit('sign:' + req.ip, 8); const d = docByToken(req.params.token); if (!req.body.agree) throw new Error('Please confirm you have read the document'); const r = L.signDoc(d, { signature: req.body.signature, name: req.body.name, ip: req.ip }); return { status: r.status, signed_at: r.signed_at }; }));
const invByToken = (t) => { const i = one('SELECT id FROM invoices WHERE token=? AND status<>?', t, 'draft'); if (!i) throw nf('Invoice not found'); return L.invoiceFull(i.id); };
app.get('/api/public/pay/:token', wrap((req) => { const i = invByToken(req.params.token); return { ...i, token: undefined, worked_cents: undefined, firm: firm() }; }));
app.post('/api/public/pay/:token', wrap((req) => { rateLimit('pay:' + req.ip, 6); const i = invByToken(req.params.token); const last4 = testCard(req.body.card); const amt = req.body.amount ? cents(req.body.amount) : i.balance_cents; const r = L.payInvoice(one('SELECT * FROM invoices WHERE id=?', i.id), { amount_cents: amt, method: 'card', reference: `Online ••${last4} (test)` }, 'Online payment'); return { status: r.status, balance_cents: r.balance_cents }; }));

// ---------------------------------------------------------------- client portal
const myClient = (u) => { const c = u.client_id && one('SELECT * FROM clients WHERE id=?', u.client_id); if (!c) throw nf('No client record linked'); return c; };
const myMatter = (u, id) => { const c = myClient(u), m = one('SELECT * FROM matters WHERE id=? AND client_id=?', Number(id), c.id); if (!m) throw nf(); return m; };
const matterPublic = (m) => { const st = L.AREAS[m.area].stages, resp = one('SELECT * FROM users WHERE id=?', m.responsible_id);
  return { id: m.id, number: m.number, title: m.title, area: L.AREAS[m.area].name, status: m.status, stage: m.stage, stages: st, stage_index: st.indexOf(m.stage), billing: m.billing, opened_on: m.opened_on, closed_on: m.closed_on, court: m.court, case_no: m.case_no, responsible: person(resp), team: all('SELECT u.name, u.title, t.role FROM matter_team t JOIN users u ON u.id=t.user_id WHERE t.matter_id=?', m.id),
    next: one("SELECT title, start_at, location, kind FROM events WHERE matter_id=? AND client_visible=1 AND done=0 AND start_at >= ? ORDER BY start_at LIMIT 1", m.id, today()), unread: one('SELECT COUNT(*) n FROM messages WHERE matter_id=? AND from_client=0 AND read_at IS NULL', m.id).n, trust_cents: L.trustBal(m.client_id, m.id), budget_cents: m.budget_cents }; };
app.get('/api/portal', auth('client'), wrap((req) => { const c = myClient(req.user), k = L.kycState(c.id), ar = L.arAging(c.id);
  return { client: c, firm: firm(), kyc: { items: k.items, complete: k.complete, status: c.kyc_status, refresh_due: k.refresh_due }, matters: all("SELECT * FROM matters WHERE client_id=? ORDER BY status='closed', opened_on DESC", c.id).map(matterPublic),
    invoices: all("SELECT i.id, i.number, i.token, i.issued_on, i.due_on, i.total_cents, i.paid_cents, i.written_off_cents, i.status, m.number AS matter_no FROM invoices i JOIN matters m ON m.id=i.matter_id WHERE i.client_id=? AND i.status NOT IN ('draft','void') ORDER BY i.issued_on DESC LIMIT 30", c.id), ar,
    to_sign: all("SELECT name, token, created_at FROM documents WHERE client_id=? AND status='sent'", c.id), tasks: all("SELECT t.*, m.number AS matter_no FROM tasks t JOIN matters m ON m.id=t.matter_id WHERE m.client_id=? AND t.for_client=1 AND t.status='open' ORDER BY due_on", c.id),
    trust_cents: L.trustBal(c.id), events: all("SELECT e.title, e.start_at, e.location, e.kind, m.number AS matter_no FROM events e JOIN matters m ON m.id=e.matter_id WHERE m.client_id=? AND e.client_visible=1 AND e.done=0 AND e.start_at >= ? ORDER BY e.start_at LIMIT 8", c.id, today()) }; }));
app.get('/api/portal/matters/:id', auth('client'), wrap((req) => { const m = myMatter(req.user, req.params.id); run('UPDATE messages SET read_at=? WHERE matter_id=? AND from_client=0 AND read_at IS NULL', now(), m.id);
  return { ...matterPublic(m), messages: all('SELECT ms.*, u.name AS author FROM messages ms LEFT JOIN users u ON u.id=ms.user_id WHERE matter_id=? ORDER BY created_at', m.id), documents: all('SELECT id, name, kind, status, token, size_kb, created_at, signed_at FROM documents WHERE matter_id=? AND client_visible=1 ORDER BY created_at DESC', m.id),
    events: all('SELECT title, start_at, location, kind, done FROM events WHERE matter_id=? AND client_visible=1 ORDER BY start_at DESC LIMIT 20', m.id), tasks: all('SELECT * FROM tasks WHERE matter_id=? AND for_client=1 ORDER BY status, due_on', m.id),
    trust: all('SELECT date, kind, amount_cents, description, reference FROM trust WHERE matter_id=? ORDER BY date, id', m.id), invoices: all("SELECT number, token, issued_on, total_cents, paid_cents, status FROM invoices WHERE matter_id=? AND status NOT IN ('draft','void') ORDER BY issued_on DESC", m.id) }; }));
app.post('/api/portal/matters/:id/messages', auth('client'), wrap((req) => { const m = myMatter(req.user, req.params.id); if (!str(req.body.body)) throw new Error('Write a message'); run('INSERT INTO messages (matter_id, from_client, body, created_at) VALUES (?,?,?,?)', m.id, 1, str(req.body.body, 4000), now()); log('matter:' + m.id, req.user.name, 'Client message'); return { ok: true }; }));
app.post('/api/portal/tasks/:id/done', auth('client'), wrap((req) => { const c = myClient(req.user), t = one('SELECT t.* FROM tasks t JOIN matters m ON m.id=t.matter_id WHERE t.id=? AND m.client_id=? AND t.for_client=1', Number(req.params.id), c.id); if (!t) throw nf();
  if (str(req.body.filename)) run('INSERT INTO documents (matter_id, client_id, name, kind, size_kb, status, client_visible, uploaded_by, created_at) VALUES (?,?,?,?,?,?,?,?,?)', t.matter_id, c.id, str(req.body.filename, 120), 'client upload', Math.max(1, Number(req.body.size_kb) || 120), 'filed', 1, req.user.name, now());
  run("UPDATE tasks SET status='done', done_at=? WHERE id=?", now(), t.id); log('matter:' + t.matter_id, req.user.name, `Client completed: ${t.title}`); return { ok: true }; }));
app.post('/api/portal/kyc', auth('client'), wrap((req) => { const c = myClient(req.user); if (!L.KYC_REQ[c.kind].some(([k]) => k === req.body.kind)) throw new Error('Unknown document'); if (!str(req.body.filename)) throw new Error('Choose a file'); L.uploadKyc(c.id, req.body.kind, str(req.body.filename, 120), req.user.name); return L.kycState(c.id); }));
app.post('/api/portal/invoices/:id/pay', auth('client'), wrap((req) => { const c = myClient(req.user), i = one('SELECT * FROM invoices WHERE id=? AND client_id=?', Number(req.params.id), c.id); if (!i) throw nf(); const last4 = testCard(req.body.card); return L.payInvoice(i, { amount_cents: i.total_cents - i.paid_cents - i.written_off_cents, method: 'card', reference: `Portal ••${last4} (test)` }, req.user.name); }));

// ---------------------------------------------------------------- staff
const staff = express.Router(); staff.use(auth('managing_partner', 'partner', 'associate', 'paralegal', 'accounts', 'reception')); app.use('/api/staff', staff);
const role = (...r) => (req, res, next) => (r.includes(req.user.role) ? next() : res.status(403).json({ error: 'Not allowed for your role' }));
const TK = role('managing_partner', 'partner', 'associate', 'paralegal'), ATTY = role('managing_partner', 'partner', 'associate'), PARTNER = role('managing_partner', 'partner'), ACCTS = role('managing_partner', 'accounts'), BILL = role('managing_partner', 'partner', 'accounts'), DESK = role('managing_partner', 'partner', 'associate', 'paralegal', 'reception', 'accounts');
const userMatterFilter = (u) => (['associate', 'paralegal'].includes(u.role) ? ` AND m.id IN (SELECT matter_id FROM matter_team WHERE user_id=${Number(u.id)})` : '');
staff.get('/meta', wrap((req) => ({ me: req.user, firm: firm(), users: all("SELECT id, name, role, title, color, rate_cents, target_hours FROM users WHERE role<>'client' AND active=1 ORDER BY CASE role WHEN 'managing_partner' THEN 0 WHEN 'partner' THEN 1 WHEN 'associate' THEN 2 WHEN 'paralegal' THEN 3 ELSE 4 END, name"),
  areas: L.AREAS, activities: L.ACTIVITIES, rules: L.RULES, templates: L.TEMPLATES, packages: L.PACKAGES, kyc_req: L.KYC_REQ })));
staff.get('/dashboard', wrap((req) => { const u = req.user, d = today(), wk = addDays(d, -((new Date(d + 'T12:00').getDay() + 6) % 7)), mo = d.slice(0, 8) + '01';
  const mine = (from) => one('SELECT COALESCE(SUM(CASE WHEN billable=1 THEN minutes END),0) b, COALESCE(SUM(minutes),0) t, COALESCE(SUM(CASE WHEN billable=1 THEN minutes*rate_cents/60.0 END),0) v FROM time_entries WHERE user_id=? AND date BETWEEN ? AND ?', u.id, from, d);
  const r = L.reports(mo, d);
  return { today: d, timer: one('SELECT t.*, m.number, m.title FROM time_entries t JOIN matters m ON m.id=t.matter_id WHERE t.user_id=? AND t.running_since IS NOT NULL', u.id),
    time: { today: mine(d), week: mine(wk), month: mine(mo), target_day: u.target_hours ? Math.round((u.target_hours / 230) * 60) : 0 },
    events: all(`SELECT e.*, m.number, m.title AS matter_title FROM events e LEFT JOIN matters m ON m.id=e.matter_id WHERE e.done=0 AND e.start_at BETWEEN ? AND ? ${['associate', 'paralegal', 'partner', 'managing_partner'].includes(u.role) ? 'AND (e.user_id=' + Number(u.id) + ' OR e.matter_id IN (SELECT matter_id FROM matter_team WHERE user_id=' + Number(u.id) + '))' : ''} ORDER BY e.start_at LIMIT 14`, d, addDays(d, 14) + ' 23:59'),
    tasks: all("SELECT t.*, m.number, m.title AS matter_title FROM tasks t JOIN matters m ON m.id=t.matter_id WHERE t.assignee_id=? AND t.status='open' ORDER BY t.due_on LIMIT 12", u.id),
    intakes: all("SELECT id, number, name, area, status, created_at, urgency FROM intakes WHERE status IN ('new','conflict_review','cleared') ORDER BY status='conflict_review' DESC, created_at DESC LIMIT 8"),
    kyc_queue: one("SELECT COUNT(*) n FROM kyc_docs WHERE status='received'").n, firm: { billed: r.billed_fees_cents, collected: r.collected_cents, wip: r.wip_total, ar: r.ar.total, ar90: r.ar.buckets.d90, trust: r.trust_cents },
    deadlines: all("SELECT e.*, m.number FROM events e JOIN matters m ON m.id=e.matter_id WHERE e.done=0 AND e.kind IN ('deadline','limitation') AND e.start_at BETWEEN ? AND ? ORDER BY e.start_at", d, addDays(d, 21) + ' 23:59') }; }));
staff.get('/search', wrap((req) => { const q = `%${String(req.query.q || '').trim()}%`; if (q.length < 4) return {}; return { clients: all('SELECT id, number, name, kyc_status FROM clients WHERE name LIKE ? OR number LIKE ? OR email LIKE ? LIMIT 6', q, q, q), matters: all('SELECT id, number, title, status FROM matters WHERE title LIKE ? OR number LIKE ? OR case_no LIKE ? LIMIT 8', q, q, q), intakes: all('SELECT id, number, name, status FROM intakes WHERE name LIKE ? OR number LIKE ? LIMIT 4', q, q) }; }));
// intake & conflicts
staff.get('/intakes', wrap((req) => all(`SELECT i.*, u.name AS consult_with FROM intakes i LEFT JOIN users u ON u.id=i.consult_user_id ${req.query.status ? 'WHERE i.status=?' : ''} ORDER BY CASE i.status WHEN 'conflict_review' THEN 0 WHEN 'new' THEN 1 WHEN 'cleared' THEN 2 WHEN 'consult_booked' THEN 3 ELSE 4 END, i.created_at DESC LIMIT 200`, ...[req.query.status].filter(Boolean)).map((i) => ({ ...i, adverse: J(i.adverse, []), conflicts: J(i.conflicts, []) }))));
staff.post('/intakes/:id/:action', DESK, wrap((req) => { const i = one('SELECT * FROM intakes WHERE id=?', Number(req.params.id)); if (!i) throw nf(); const a = req.params.action, b = req.body;
  if (a === 'clear') { if (!PARTNERS.includes(req.user.role)) throw Object.assign(new Error('Only a partner can clear a conflict'), { status: 403 }); run("UPDATE intakes SET status='cleared', cleared_by=?, conflict_note=? WHERE id=?", req.user.name, str(b.note, 500), i.id); log('intake:' + i.id, req.user.name, 'Conflicts cleared'); return { ok: true }; }
  if (a === 'decline') { run("UPDATE intakes SET status='declined', cleared_by=?, conflict_note=? WHERE id=?", req.user.name, str(b.note, 500) || 'Unable to act', i.id); L.notify({ to: i.email, kind: 'intake', subject: 'Your enquiry', body: `Dear ${i.name}, thank you for contacting us. Unfortunately we are unable to act in this matter. We recommend you seek independent advice promptly, as time limits may apply.` }); return { ok: true }; }
  if (a === 'book') { if (!isDate(b.date) || !isTime(b.time)) throw new Error('Choose a time'); return L.bookConsult(i, { user_id: Number(b.user_id), date: b.date, time: b.time, mode: b.mode, paid: true }, req.user.name); }
  if (a === 'convert') { if (!['managing_partner', 'partner', 'associate'].includes(req.user.role)) throw Object.assign(new Error('An attorney must open the matter'), { status: 403 }); return L.convertIntake(i, { responsible_id: Number(b.responsible_id) || req.user.id, title: str(b.title, 160), billing: ['hourly', 'fixed', 'capped'].includes(b.billing) ? b.billing : 'hourly', fixed_fee_cents: b.fixed_fee ? cents(b.fixed_fee) : null, cap_cents: b.cap ? cents(b.cap) : null, evergreen_cents: b.evergreen ? cents(b.evergreen) : 0, client_id: Number(b.client_id) || null }, req.user.name); }
  if (a === 'lost') { run("UPDATE intakes SET status='lost' WHERE id=?", i.id); return { ok: true }; }
  throw new Error('Unknown action'); }));
const PARTNERS = ['managing_partner', 'partner'];
