// trust
staff.get('/trust', role('managing_partner', 'partner', 'accounts'), wrap(() => ({ ...L.reconciliation(), recent: all('SELECT t.*, c.name, m.number AS matter_no FROM trust t JOIN clients c ON c.id=t.client_id LEFT JOIN matters m ON m.id=t.matter_id ORDER BY t.date DESC, t.id DESC LIMIT 60') })));
staff.post('/trust/deposit', ACCTS, wrap((req) => { const b = req.body; return L.trustDeposit({ client_id: Number(b.client_id), matter_id: Number(b.matter_id) || null, amount_cents: cents(b.amount), reference: str(b.reference, 60), cleared: b.cleared !== false }, req.user.name); }));
staff.post('/trust/disburse', ACCTS, wrap((req) => { const b = req.body; return { id: L.trustDisburse({ client_id: Number(b.client_id), matter_id: Number(b.matter_id), amount_cents: cents(b.amount), description: str(b.description, 160) || 'Disbursement', kind: b.kind === 'refund' ? 'refund' : 'disbursement', reference: str(b.reference, 60) }, req.user.name) }; }));
staff.post('/trust/reconcile', ACCTS, wrap((req) => { const b = req.body; if (b.clear_ids) for (const id of b.clear_ids) run('UPDATE trust SET cleared=1 WHERE id=?', Number(id)); if (b.bank != null && b.bank !== '') { setSetting('trust_bank_balance', cents(b.bank)); setSetting('trust_bank_date', isDate(b.date) ? b.date : today()); } log('trust', req.user.name, 'Reconciliation updated'); return L.reconciliation(); }));
// calendar, reports, admin
staff.get('/calendar', wrap((req) => { const from = isDate(req.query.from) ? req.query.from : today(), to = isDate(req.query.to) ? req.query.to : addDays(from, 34); return all(`SELECT e.*, m.number, m.title AS matter_title, u.name AS who, u.color FROM events e LEFT JOIN matters m ON m.id=e.matter_id LEFT JOIN users u ON u.id=e.user_id WHERE e.start_at BETWEEN ? AND ? ${req.query.user_id ? 'AND e.user_id=' + Number(req.query.user_id) : ''} ORDER BY e.start_at`, from, to + ' 23:59'); }));
staff.get('/reports', role('managing_partner', 'partner', 'accounts'), wrap((req) => { const to = isDate(req.query.to) ? req.query.to : today(), from = isDate(req.query.from) ? req.query.from : addDays(to, -364); return L.reports(from, to); }));
staff.get('/outbox', wrap(() => all('SELECT o.*, c.name AS client FROM outbox o LEFT JOIN clients c ON c.id=o.client_id ORDER BY o.id DESC LIMIT 250')));
staff.get('/team', role('managing_partner'), wrap(() => all("SELECT id, name, email, role, title, rate_cents, target_hours, color, active FROM users WHERE role<>'client' ORDER BY role, name")));
staff.put('/team/:id', role('managing_partner'), wrap((req) => { run('UPDATE users SET rate_cents=COALESCE(?,rate_cents), target_hours=COALESCE(?,target_hours), title=COALESCE(?,title), active=COALESCE(?,active) WHERE id=?', req.body.rate != null ? cents(req.body.rate) : null, req.body.target_hours != null ? Number(req.body.target_hours) : null, str(req.body.title, 80), req.body.active == null ? null : req.body.active ? 1 : 0, Number(req.params.id)); return { ok: true }; }));
staff.post('/team', role('managing_partner'), wrap((req) => { const b = req.body, email = str(b.email, 200)?.toLowerCase(); if (!str(b.name) || !email) throw new Error('Name and email required'); if (one('SELECT 1 FROM users WHERE email=?', email)) throw new Error('Email in use'); const temp = crypto.randomBytes(5).toString('hex'); run('INSERT INTO users (email,password_hash,role,name,slug,title,rate_cents,target_hours,created_at) VALUES (?,?,?,?,?,?,?,?,?)', email, hashPassword(temp), ['partner', 'associate', 'paralegal', 'accounts', 'reception'].includes(b.role) ? b.role : 'associate', str(b.name, 80), str(b.name, 80).toLowerCase().replace(/[^a-z]+/g, '-'), str(b.title, 80), cents(b.rate || 0), Number(b.target_hours) || 0, now()); return { tempPassword: temp }; }));
staff.post('/portal-invite/:clientId', role('managing_partner', 'partner', 'associate', 'reception'), wrap((req) => { const c = one('SELECT * FROM clients WHERE id=?', Number(req.params.clientId)); if (!c?.email) throw new Error('Client needs an email address'); if (one('SELECT 1 FROM users WHERE client_id=?', c.id)) throw new Error('This client already has portal access'); const temp = crypto.randomBytes(5).toString('hex');
  run('INSERT INTO users (email,password_hash,role,name,client_id,created_at) VALUES (?,?,?,?,?,?)', c.email.toLowerCase(), hashPassword(temp), 'client', c.contact_name || c.name, c.id, now()); L.notify({ client_id: c.id, kind: 'invite', subject: 'Your secure client portal', body: `Sign in at ${setting('public_url', '')}/login with ${c.email} and temporary password ${temp}.` }); return { tempPassword: temp }; }));

// ---------------------------------------------------------------- pages
const page = (f) => (req, res) => res.sendFile(path.join(ROOT, 'public', f));
app.get(['/console', '/console/'], page('console.html')); app.get('/login', page('login.html')); app.get(['/portal', '/portal/'], page('portal.html'));
app.get(['/i/:token', '/sign/:token', '/pay/:token'], page('guest.html')); app.get(['/insights/:slug', '/people/:slug'], page('index.html'));
app.use(express.static(path.join(ROOT, 'public'), { ...so, extensions: ['html'] }));
app.use('/api', (req, res) => res.status(404).json({ error: 'Not found' }));
app.use((req, res) => res.status(404).sendFile(path.join(ROOT, 'public', 'index.html')));
const PORT = Number(process.env.PORT) || 3700; app.listen(PORT, () => console.log(`ADDERLEY MOSS on http://localhost:${PORT}`));
